window.DEEPWOKEN_DATA = window.DEEPWOKEN_DATA || {};
window.DEEPWOKEN_DATA.weaponsRu = {"adretian-aegis": {"description": "Прочный щит, который традиционно изготавливают под стать рангу владельца.", "special_effect": "Щит: при хвате одной рукой Стойка (Posture) персонажа увеличивается на бонус максимальной Стойки щита, но восстановление Стойки при парировании снижается на 40%.\n\nЦепь командования (Chain of Command): Adretian Aegis меняет цвет в зависимости от вашего текущего подразделения Authority Ensign. Если игрок не Authority Ensign, щит остаётся стандартного цвета: синий с золотыми акцентами."}, "adretian-axe": {"description": "Составной топор в типичной адретианской манере."}, "alloyblood-axe": {"description": "Большой топор из сплавленной крови (alloyblood), которую вы собрали с противника.", "special_effect": "Alloyblood Weapon: оружие из alloyblood можно дополнительно улучшить, взяв определённые таланты Composite Path: Alloyblood."}, "alloyblood-daggers": {"description": "Парные кинжалы из сплавленной крови (alloyblood), которую вы собрали с противника.", "special_effect": "Alloyblood Weapon: оружие из alloyblood можно дополнительно улучшить, взяв определённые таланты Composite Path: Alloyblood."}, "alloyblood-spear": {"description": "Копьё из сплавленной крови (alloyblood), которую вы собрали с противника.", "special_effect": "Alloyblood Weapon: оружие из alloyblood можно дополнительно улучшить, взяв определённые таланты Composite Path: Alloyblood."}, "anklets-of-alsin": {"description": "[ТРЕБУЕТ СТИЛЯ БОЯ НОГАМИ]"}, "apprentice-rapier": {"description": "Хотя этот клинок для новичков выглядит хрупким, с него начали путь многие Pathfinder."}, "avenger": {"description": "Двуручный меч, переданный вам предками."}, "battleaxe": {"description": "Прочный топор, идеально подходящий для раскалывания костей."}, "bellmarrow-reave": {"description": "Выкованный из закалённых внутренних панцирей местных Arkasid с Simforea и скреплённый фрагментами местной флоры, этот твинблейд несёт безошибочную печать обитающего здесь Anansi Knell. Его парные лезвия испещрены неистовой резьбой по кости: хитрые узоры, похожие на сталкивающиеся колебания, будто звук, раздирающий сам себя на отражение."}, "big-brother": {"description": "Подарок High Inquisitor Merey. Это совсем не оружие войны, а идеальный инструмент для скрытных «мокрых» заданий Инквизиции. Глаза и уши могут наблюдать и слушать, но никогда не должны издавать ни звука."}, "black-death": {"description": "Орудие Ministry. В отличие от своего собрата, эта пика не заботится о беспорядке, который оставляет после себя."}, "bloodbane": {"description": "Реликвия Canor Borderwatcher: этот пропитанный кровью цвайхандер веками передавали их предводители. Порой вы готовы поклясться, что чувствуете, как внутри отдаётся биение сердца."}, "bloodfouler": {"description": "Тёмно-багровый одачи, заказанный и выкованный для будущего пророка, а затем оставленный годы спустя. На нём клеймо мастера, и зловещая клятва сочится сквозь алые волокна. Зазубренное лезвие рассекает врагов с пугающей лёгкостью, жадно пьёт их кровь и питает божественное предназначение владельца. Когда пальцы касаются зазубренного края, в голове мелькают невиданные ужасы: короткие проблески чего-то огромного и непостижимого. Видения исчезают раньше, чем вы успеваете понять их смысл, и остаётся лишь вопрос... это эхо прошлого или предвестие грядущего?", "special_effect": "Восстанавливает владельцу процент крови при попадании обычной атакой (M1)."}, "boltcrusher": {"description": "Передовое творение Deepdelver, особым образом переделанное из их знаменитых взрывных кирок. Этот бурильный инструмент создан, чтобы добывать и разрушать самые твёрдые материалы глубин, а также тех, кто не держит слово в сделке. Пропитанная потрескивающим Thundercall, эта махина направляет грохочущие молнии с каждым ударом, обращая скалу в щебень, а врагов в осколки. От глубин до вершин по всей земле инструменты Union вспыхивают, и путь прорывается взрывом. Мы идём вперёд, питаемые искрой."}, "bronze-aspis": {"description": "Круглый деревянный щит, который часто сочетают с копьём или коротким клинком.", "special_effect": "Щит: при хвате одной рукой Стойка (Posture) персонажа увеличивается на бонус максимальной Стойки щита, но восстановление Стойки при парировании снижается на 40%."}, "calamity-cinnabar": {"description": "Клинок, как говорят, выкованный из останков Last Dead, последних счастливцев в конце Canticlysm, которых пощадило Drowning.", "special_effect": "При попадании накладываются некоторые пассивки Shadowcast."}, "canorian-axe": {"description": "Топор, похожий на те, что когда-то носили Canor Swornfang, верные защитники ранней Адретианской империи."}, "carrions-moonseye-scalpel": {"description": "Доработка чертежей оружейника Rosen, выполненная оружейником Hierka, бывшим учеником Rosen. Говорят, Hierka скрывал, что был членом Bureau of Research при Authority, чтобы выкрасть секреты Summer Company."}, "cavalry-saber": {"description": "Для людей нынешнего мира идея кавалерии кажется нелепой. Тем не менее кавалерийская сабля продолжает жить как эффективный клинок для налётов."}, "central-dirk": {"description": "Короткий клинок вроде боевого ножа, стандартное снаряжение солдат Central Authority."}, "cerulean-thread": {"description": "Оружие бывшего ученика 4th Prophet, который быстро поднялся в рядах Ministry благодаря собственной изобретательности и доработкам кукольных нитей Zi'eer. Погиб от руки Maestro, под видом Vigil Instructor собирая сведения. Разглядев маскировку, Maestro бросил вызов самозваному инструктору и заставил его раскрыть карты. Когда в рукаве не осталось уловок, тот пал перед арсеналом Maestro, а его творение пополнило коллекцию."}, "champions-dagger": {"description": "Клинок, которым гордятся те, кто прошёл испытания «Golden Rat». Под стать чемпиону, его металл сияет так же ярко, как дух самого Golden Rat."}, "champions-sword": {"description": "Клинок, которым гордятся те, кто прошёл испытания «Golden Rat». Под стать чемпиону, его металл сияет так же ярко, как дух самого Golden Rat."}, "chorus-of-agonies": {"description": "Возвышаясь над испытанием, словно монумент, присутствие Enmity вытягивает воздух из лёгких, давящее и непреклонное, будто само полно презрения. Теперь, в ваших руках, мерзкий топор пульсирует жутким ритмом, сердцебиением, сплетённым из муки бесчисленных замученных душ. Воздух сгущается под его тяжестью, каждый изгиб скрученного оружия ненавидит собственное существование. Проклятые стражи внутри молят об освобождении, и их скорбная песнь терзает ваш дух. Но вы стоите твёрдо и встречаете бездну с вызовом. Chorus of Agonies окутывает вас."}, "coldpoint": {"description": "Эта длинная сосулька добыта в верхней корке Second Layer и вечно остаётся замороженной по клятве. На рукояти клеймо ледяного Kyrsan. До прихода Ethiron такое оружие делали как лёгкие тренировочные клинки для Kyrsan, хотя в наших руках нам нет нужды сдерживаться."}, "corvidirge-severants": {"description": "Парные косы, выкованные из металлических когтей и перьев Harrow, пришедших из Пустоты, жуткого существа Boundary. Тёмные металлы и оперение слились в пару изящных потусторонних клинков, чьё лезвие, кажется, никогда не тупится.", "special_effect": "Это оружие может активировать таланты как Twinblade, так и Dagger, а также общие таланты для среднего и лёгкого оружия. Сюда входят способности Silentheart для лёгкого и среднего оружия."}, "crescent-cleaver": {"description": "Такие большие клинки часто используют охотники на чудовищ: зазубренное лезвие гарантирует, что даже если добыча убежит, им достаточно идти по следу крови."}, "crucible-rapier": {"description": "Говорят, дворяне Celtor когда-то дрались этим благородным оружием, и споры их теперь забыты. Дом их потерян, но оружие осталось."}, "crypt-blade": {"description": "Клинок, как говорят, выкованный из останков Last Dead, последних счастливцев в конце Canticlysm, которых пощадило Drowning."}, "cursed-flames": {"description": "Клинок, пропитанный словами Hero, вызывает невыносимый жар геотермальных источников.", "special_effect": "Обычные атаки накладывают Cursed Burn."}, "curved-blade-of-winds": {"description": "Ценный клинок, который, как считается, выковали во время Canticlysm первые Galebreather."}, "darksteel-cleaver": {"description": "Когда шансы безнадёжны, иногда всё, что нужно, это Большой Меч."}, "darksteel-greatsword": {"description": "Эти клинки из прочной тёмной стали популяризировал Ignition Union как инструмент против Deep."}, "dawnshot": {"description": "С почти безупречным серебряным блеском, не дающим морской соли разъедать металл, Dawnshot был специально создан Rosen для долгих морских путешествий. Малую дальность компенсирует почти ломающая запястье отдача четырёх стволов. Впрочем, поскольку пушка Summer Company сделала большинство морских вложений на их территориях бесполезными, это оружие сняли с производства."}, "deaths-reverie": {"description": "Ягнята перестали кричать?"}, "deconstruction-of-shrine": {"description": "Художественная деконструкция загадочных святилищ глубин, разбросанных по поверхности. Автор L. O. Dise.", "special_effect": "Щит: при хвате одной рукой Стойка (Posture) персонажа увеличивается на бонус максимальной Стойки щита, но восстановление Стойки при парировании снижается на 40%."}, "deepcrushersword": {"description": "Говорят, кузнецы всегда держат такой под рукой на случай, если кто-то откажется платить по счёту."}, "deepspindle": {"description": "Клинок этой рапиры выкован не в традиционном смысле, а выращен из самого тёмного шлака бездны и принял форму извивающейся злобной тени. Рассказывают о благородном воине из Celtor, который, обнаружив древние проходы Ministry, был поглощён извращённым любопытством и выпестовал этот мерзкий клинок. По мере тёмного ритуала душа воина всё глубже уходила во тьму, суть разлагалась, а разум рассыпался в безумие. В итоге, поддавшись глубинам, пробуждается Deepspindle.", "special_effect": "Синергирует с Deepscorn Casque и Darkened Bastion."}, "depthsplitter": {"description": "Древний etrean-твинблейд, недавно найденный вновь, когда всплыл фрагмент driftland и открыл останки давно потерянного etrean-взвода, погибшего и унесённого пустотой много веков назад. Теперь это оружие, считавшееся утраченным, вернулось в обращение и несёт эхо забытых сражений."}, "dissonant-chimecaller": {"description": "Неожиданно изысканный посох старинной работы. В отличие от нынешнего состояния Knell, кажется, он создан в то время, когда тот ещё мог быть самим собой."}, "dormant-splinter": {"description": "Этот клинок из Umbrite не похож ни на что, с чем вы сталкивались. Отмеченный и повреждённый годами, он остаётся одновременно текучим и жёстким, что не поддаётся пониманию. Когда рядом оказывается другое оружие из вашей коллекции, крошечные волокна цепляются за его поверхность, дрожат и возвращаются в исходное состояние, как будто клинок пробует на вкус и ищет достойную пару."}, "dragoon": {"description": "Механизмы этого огнестрельного оружия изготовлены куда тщательнее, чем у его массовых собратьев, и такие экземпляры часто встречаются как предметы коллекций над каминами богачей."}, "duskguard-axe": {"description": "Могучий топор, который носят самые уважаемые люди Authority. Его вес и сила удара обрушивают на врагов поистине жестокие удары."}, "duskshot": {"description": "С почти безупречным серебряным блеском, не дающим морской соли разъедать металл, Dawnshot был специально создан Rosen для долгих морских путешествий. Малую дальность компенсирует почти ломающая запястье отдача четырёх стволов. Впрочем, поскольку пушка Summer Company сделала большинство морских вложений на их территориях бесполезными, это оружие сняли с производства."}, "ebonshard-lexicon": {"description": "Хм-хм-хм...", "special_effect": "Анимация First Light."}, "edenbrand-hellcoil": {"description": "Пропитанная дыханием настоящего Edenkite, эта пушка хранит угасающие остатки существа, убитого прославленным северным тиранским охотничьим отрядом. Заманив зверя в ущелье, отряд сразил его шквалом пушечного огня с утёсов. Но судьба распорядилась так, что на обратном пути шторм сбил их судно в Voidsea, унеся и их, и добычу за пределы карты. Теперь его пронзительно холодный soulfire попал в ваши руки.", "special_effect": "Критический удар накладывает White Burn."}, "enforcers-axe": {"description": "Титаны, известные как Enforcer, верные слуги Cathedral, редко встречаются за её пределами. Говорят, это замученные души тех, кто провалил Trial, превращённые в чудовищ, отказывающих смертным душам в спасении."}, "enforcers-blade": {"description": "Титаны, известные как Enforcer, верные слуги Cathedral, редко встречаются за её пределами. Говорят, это замученные души тех, кто провалил Trial, превращённые в чудовищ, отказывающих смертным душам в спасении."}, "enforcers-hammer": {"description": "Титаны, известные как Enforcer, верные слуги Cathedral, редко встречаются за её пределами. Говорят, это замученные души тех, кто провалил Trial, превращённые в чудовищ, отказывающих смертным душам в спасении."}, "ethiron-curseshield": {"description": "Щит, выкованный, чтобы выдержать самые суровые ветра Ethiron, сделанный вручную теми, кто искал удачи среди руин.", "special_effect": "Щит: при хвате одной рукой Стойка (Posture) персонажа увеличивается на бонус максимальной Стойки щита, но восстановление Стойки при парировании снижается на 40%."}, "eye-of-malice": {"description": "Созданный из останков Caeranthil's Doom, клинок извивается, как живой, дёргаясь и царапая ваших врагов издалека. Submergence of the Southern Luminant совершил не только Horror, погрузивший Celtor в Depths, но и бесчисленные меньшие трагедии, заглушённые масштабом катастрофы. Среди них левиафан, известный как Doom of Caeranthil, названный в честь земли, которую он тоже утащил вниз. Во многом знание о Caeranthil сохранилось лишь сквозь линзу кошмаров, поглотивших её. Культура, еда, смех, шутки для своих, мелкие споры, моды, по которым они одевались... Как мы можем пережить всё это, если не осталось никого, кто бы помнил?", "special_effect": "Обычные атаки накладывают Mark of Malice, усиливающую критический удар."}, "eyes-of-ethiron": {"description": "Прикосновение кузни сдирает слои пересказов истории и обнажает прошлое клинка. Godstorm, ветер, несший тень. Око в сердце каждой завивающейся спирали. Задолго до того, как Drallis укротил его, и до прихода Tides, именно размышляя о разрушениях, которые он принёс, человечество вырастило искусство, ставшее Galebreathing. Однако, возможно из-за своей музы, это зарождающееся искусство стало и основой Shadowcasting. В некотором смысле лишь в годы, когда Godstorm дремал, ветер и тень можно было считать отдельными."}, "falchion": {"description": "Однолезвийная сабля, которую часто носят призванные в Authority ополченцы из-за простоты изготовления."}, "false-memory": {"description": "Фрагменты клинка словно уплывают в бескрайнюю пустоту вокруг вас. Это продлится недолго, позволяя вам сменить оружие в Hippocampal Pool."}, "first-light": {"description": "Клинок Venn Kaelhand, ученика Pleeksty, слишком глубоко погрузившегося в изучение зверей, изменённых влиянием Korlfiend. Встретил свою судьбу в пасти уникального экземпляра Megalodaunt, который, как говорят, подвергся воздействию жерл Korilfiend.", "special_effect": "При критическом ударе призывает бурю огненных клинков, обрушивающихся на поле боя."}, "flareblood-kamas": {"description": "Извращённое оружие, созданное Scholar of the Burning Blood, Chaser, во время его ученичества у Second Prophet. Внутри бурлит кипящая смесь заражённой крови, ожидающая освобождения из своей темницы."}, "flintlock": {"description": "Сын деревенского кузнеца, юный оружейник Rosen ушёл в море и вернулся постаревшим, привезя искру вдохновения, подарившую миру огнестрельное оружие. Современный кремнёвый пистолет — улучшенная и облегчённая версия прототипа оружейника, которую теперь можно встретить в каждом Luminant."}, "fondant-splitter": {"description": "Это безопасно есть? Сейчас узнаем...", "special_effect": "Критический удар лечит владельца. Количество исцеления можно увеличить талантами Umami и Tavernkeep."}, "fools-tankard": {"description": "Вы окончательно сошли с ума."}, "forge-greathammer": {"description": "Говорят, кузнецы всегда держат такой под рукой на случай, если кто-то откажется платить по счёту."}, "forgotten-gladius": {"description": "Его носили на поясе конных офицеров во время Canticlysm. Многие послеприливные годы это была лишь диковинка, перед которой заискивали мелкие дворяне. Несмотря на название, модным его сделали молодые морские офицеры Authority, увидевшие ценность в унаследованных безделушках и вытащившие клинок из безвестности."}, "formless-shard": {"description": "Когда-то это было вещью. Теперь просто осколок."}, "fractine": {"description": "Злополучный клинок пустоты, когда-то целый, а ныне нет.\nСвязанный Vow с душой прежнего владельца; душа теперь взята пустотой, разбита, осколки; через Vow клинок теперь надломленный остаток, подобие того, чем он когда-то был."}, "frost-gauntlets": {"description": "Идеально для «Knuckle Sandwich», поданного холодным."}, "frostthorn": {"description": "Сложный пружинный механизм внутри этого оружия позволяет слоистым лезвиям раскрываться веером. Металл излучает постоянный холод и звенит, как кристалл, при соприкосновении с любой поверхностью. Несомненно, для Kyrsan это необычное оружие, учитывая, где вы его нашли. Возможно, это боевой трофей, заново переделанный под новую цель?..."}, "gale-pale": {"description": "Кустарная переделка старого верного большого молота. Покрытый серебром, этот Pale Morning скользит по течению ветров, словно ничто, и крушит противников."}, "gaunts-of-enmity": {"description": "Перчатки великой силы, выкованные давным-давно, чтобы укреплять владельца и разбивать души слабых."}, "gilded-knife": {"description": "Нож тонкой работы с такой же тонкой остротой."}, "golden-swordfish": {"description": "Легендарный улов рыбака, которому нет равных. Море дрожит в вашем кильватере."}, "gourdguard": {"special_effect": "Щит: при хвате одной рукой Стойка (Posture) персонажа увеличивается на бонус максимальной Стойки щита, но восстановление Стойки при парировании снижается на 40%."}, "gran-sudaruska": {"description": "В последних вздохах Sudaruska the Unbroken вложила саму свою суть в это оружие, прорубаясь сквозь сотни древних Ministry как последний рубеж, защищавший Minityrsa. Теперь, когда её смертной оболочки больше нет, она стала Gran Sudaruska.", "special_effect": "*Говорит при убийстве NPC Ministry, Contractor или пользователей Prophet's Cloak."}, "gremorian-longspear": {"description": "За безопасными стенами эти длинные копья используют Children of Navae, чтобы защищаться в глуши.", "special_effect": "У оружия критический удар с подтягиванием: владелец метает копьё и подтягивает пораженную цель."}, "guiding-star": {"description": "Лук, священный для Children of Navae. Guiding Star используют на Festival of Lights претенденты, стремящиеся доказать себя в испытаниях. В этих испытаниях участники должны охотиться на волка с завязанными глазами, используя лишь остальные чувства, чтобы выслеживать и оставаться незамеченными. Если волк вонзит клыки в участника или оставит на нём хоть какую-то метку, тот дисквалифицируется. Сам лук тоже своего рода диковина: его стрелы создаются из Ether владельца и направляются его собственной волей. Многие прошлые победители испытаний говорят, что Guiding Star говорит с ними успокаивающим голосом и подталкивает в верном направлении."}, "hailbreaker": {"description": "С разработкой Railblade Union получил преимущество над Diver в спорах за места раскопок. В ответ механики Citadel изменили подход к производству снаряжения и тесно сотрудничали с оружейниками Authority, чтобы создать хладнокровный клинок, способный пробивать шкуру чудовищ и замораживать их внутренности. В итоге получилось оружие, превосходное не только на заданиях, но и в стычках с более территориальными отрядами экспедиторов Union. Порой злость оказывается лучшим двигателем перемен."}, "halberd": {"description": "Стандартная алебарда Authority, которую часто видно в крупных стычках."}, "hallowscleave": {"description": "Клинок, как говорят, созданный семьёй Spellhardt, чтобы улаживать споры в праздничном стиле. В обычной таверне он наверняка привлечёт странные взгляды, но нужно просто выразить свой дух Hallowtide."}, "handcuffs": {"description": "Ваше надёжное оружие.", "special_effect": "Вы не можете использовать мантры. Это оружие нельзя снять, но можно убрать, поговорив с кузнецом. Ваши обычные атаки (M1) сбивают цель с ног (ragdoll) при попадании."}, "hero-blades": {"description": "Клинок, как говорят, оснащённый руной с отрывком песни, пробуждает заключённую в нём стихию."}, "heros-blade-of-flame": {"description": "Клинок, наделённый рунами слов Hero, вызывает невыносимый жар геотермальных источников."}, "heros-blade-of-frost": {"description": "Клинок, наделённый рунами слов Hero, вызывает ледяное забвение холодных пустошей."}, "heros-blade-of-lightning": {"description": "Клинок, наделённый рунами слов Hero, вызывает волосы дыбом от тревожного ожидания грозы."}, "heros-blade-of-shadow": {"description": "Клинок, наделённый рунами слов Hero, вызывает беспощадную пустоту самых тёмных теней."}, "heros-blade-of-wind": {"description": "Клинок, как говорят, оснащённый руной с отрывком песни, вызывает неотвратимую силу урагана."}, "hivelords-hubris": {"description": "...Это не очень эффективно."}, "hunting-bow": {"description": "Кролик или утка, в любой сезон, это не так уж важно."}, "icarus-sun-shield": {"description": "Щиты щитоносцев Legion часто украшают ликами знаменитых воинов, которыми те восхищаются.", "special_effect": "При хвате одной рукой восстановление Стойки при парировании снижается на 40%."}, "icepick": {"description": "Как будто он вырос прямо изо льда, но этого ведь не может быть, правда?"}, "imperators-edge": {"description": "Гигантское большое копьё, чей наконечник пропитан самой сутью света, сияет как маяк несокрушимой силы и стойкости. Его несут во главе Hundred Legions, и оно освещает им путь ослепительным блеском: символ упорства, пронзающий тени и ведущий к неизбежной победе."}, "imperial-staff": {"description": "Легендарный посох Legion Praetorian давних эпох. В его руках, как говорят, один взмах стирал с лица земли целые города и быстро расширял границы их территорий. Правдивость этих рассказов оспаривается, но необычные свойства оружия придают им некоторую достоверность."}, "infected": {"description": "Заражён...", "special_effect": "Атаки оружием заражают других игроков, превращая их в Gourdskipper и награждая вас Joy."}, "inquisitors-thorn": {"description": "Обманчиво быстрый клинок, которым когда-то пробивали панцири неукротимых Crustaceous Rex члены злополучного «Expeditionary Corps» Authority."}, "iron-birch": {"description": "Кузнецы Hive часто украшают своё оружие уникальной флорой родных мест. Одни из лучших существующих ботанических записей мира находятся на лезвиях топоров."}, "iron-blunderbuss": {"description": "Простой и потрёпанный по виду, этот образец знаний оружейника Rosen выбирает более агрессивный и рискованный способ применения. Дальности ему не хватает, зато в ближнем бою он показывает лишь жестокость как один из самых ранних оружейных экспериментов Summer Company."}, "iron-requiem": {"description": "Благодаря обратной разработке украденных партий оружия Summer Company в последнее время Ironsinger нашли выгодное ремесло в изготовлении оружия и снаряжения. Будучи местом возрождения этого искусства, Ignition Union направил это богатство на производство оружия с активными компонентами Ironsing."}, "iron-spear": {"description": "Копьё, идеальное для тыканья с безопасного расстояния."}, "iron-twinblade": {"description": "Скромный твинблейд, вдохновлённый вращающимися etrean-клинками древности. Хотя некоторые считают его неудобным и непрактичным, те, кто выбирает это оружие, ищут нечто гораздо большее, чем простое удобство. Их цель не лёгкость в обращении, а мастерство, мощь и неумолимый импульс, которые способен дать только такой клинок."}, "ironcry": {"description": "Старый, антикварный охотничий лук с мощной тетивой, лучшие дни которого, похоже, позади."}, "irontusk": {"description": "Копьё, переданное вам предками."}, "jus-karita": {"description": "Традиционный стиль боевых искусств Justicar."}, "kanabo": {"description": "Когда-то основа арсенала Etrea, известная своими размерами и грубой силой, она была оружием тяжёлой пехоты King's Guard. Эти закованные в железо воины использовали канабо, чтобы исполнять волю короля и поддерживать порядок по всему Etrean Luminant. Сегодня его применяют значительно реже: Etrea предпочитает развивать свои клинки."}, "karita-plating": {"description": "Разработанные Konga the 2nd, эти пластины помогают владельцу гораздо легче скользить по жёстким поверхностям. Это усиливает возможность атаковать печально известным Slider Style рода Konga."}, "katana": {"description": "Превосходный клинок etrean-работы, который, как говорят, вписал имя раннего Kingdom of Etrea на карту.", "special_effect": "Это оружие получает бонус урона 25% / 5% от таланта Paired Soul и выигрывает от Poser's Ring."}, "keyblade": {"special_effect": "Критический удар Hero Blade of Wind."}, "kindred-edict": {"description": "Клинок из бледного металла, добытого мастерами Starkindred на местах падения Celestial. Почти невесомый, такой клинок — основа Запада среди приверженцев веры. Когда человек пролил достаточно собственной крови на службе Церкви, ему вручают оружие, трижды омытое священным ихором Celestial.", "special_effect": "Перезарядка критического удара сбрасывается при попадании, и его можно использовать несколько раз.\nНакладывает Wither при критическом ударе, если крылья Starkindred раскрыты."}, "kite-shield": {"description": "Прекрасный щит, чтобы сдерживать ужасы мира.", "special_effect": "Щит: при хвате одной рукой Стойка (Posture) персонажа увеличивается на бонус максимальной Стойки щита, но восстановление Стойки при парировании снижается на 40%."}, "krulian-knife": {"description": "Исключительно острый нож, выкованный неизвестным способом. Окружён аурой сильного предчувствия беды.", "special_effect": "Krulian Charge: при использовании критического удара вы получаете эффект Krulian Charge, дающий Speed Boost, увеличение скорости взмаха и розовый эффект Shock на атаках оружием."}, "kyrsglaive": {"description": "Древнее копьё работы Kyrsan, само его присутствие за пределами Second Layer — чудо. Человечество находило их лишь считанные разы. В отличие от обычного оружия Kyrsan, это копьё выковано, чтобы подчинять необузданную дикую силу их сородичей. Сделанные из останков первобытных хрящевых существ, с которыми они когда-то делили мир, эти орудия были попыткой обуздать силу диких предшественников. Со временем такое оружие забросили ради холодной точности ледяных копий Kyrsan."}, "kyrsieger": {"description": "Падение Constellia возвестил разрушительный шквал из сотни Kyrsieger, пронзивших её кристальные арки. Пожалуй, самое известное оружие арсенала Kyrsan: взрывную мощь клинка можно вызвать только торжественной молитвой Ethiron. Слова этой молитвы вползают в разум владельца, хочет он того или нет."}, "kyrstear": {"description": "Подходит для непредсказуемых движений Kyrsgarde."}, "kyrswynter": {"description": "Выкованная в эпоху, потерянную для истории, и поднятая из Eternal Gale, эта реликвия родом из забытой эры. Последний шёпот своего рода, она пришла из времени до того, как народ New Kyrsa подчинился власти Drowned God Ethiron. Копьё чрезвычайно холодное на ощупь, тревожный холод липнет к коже и оставляет длительное онемение. Оно воплощает тонкое и изысканное мастерство Kyrsgarde, показывая их элегантность и утончённость до порчи. Хотя Kyrsgarde всё ещё носят копья мороза, мастерство их нынешнего оружия не идёт ни в какое сравнение: оно стало грубым и безвдохновенным под гнётом Ethiron."}, "legion-cestus": {"description": "Цестусы, которые используют члены Hundred Legions."}, "legion-shield": {"description": "Щиты щитоносцев Legion часто украшают ликами знаменитых воинов, которыми те восхищаются.", "special_effect": "Щит: при хвате одной рукой Стойка (Posture) персонажа увеличивается на бонус максимальной Стойки щита, но восстановление Стойки при парировании снижается на 40%."}, "lights-final-toll": {"description": "Напоминание о том, что все песни должны закончиться."}, "lumensplitter": {"description": "Мерзкий зазубренный клинок, сделанный в подражание челюстям, поглотившим остров Caeranthil, сверкающие врата Celtor. Подобно безумию, которое следует, когда тело падает в воду, затопление Юга было каскадом бедствий, следовавших одно за другим."}, "mace": {"description": "Простое дробящее оружие, эффективное для пробития блока."}, "markors-inheritor": {"description": "Blade Scholar из Markor, которые, как говорят, каталогизируют сам мир, странствуют из земли в землю, собирая сведения силой своих клинков. Осваивая стили боя из разных уголков моря, они практикуют своё искусство через сам клинок.", "special_effect": "Наследует критический удар вашего последнего использованного стиля Fist."}, "messer": {"description": "Многие считают его разросшимся кухонным ножом, но Messer любят следопыты и охотники на чудовищ по всему миру."}, "metal-greatsword": {"description": "Меч, который вы призвали с помощью металлических стержней противника.", "special_effect": "Урон вашего Metal Armament увеличен на 50%.\nПревращается в оружие Alloyblood, если у игрока есть талант Hypoferritinemia."}, "moon-blades": {"description": "Извращённое оружие, созданное Scholar of the Burning Blood, Chaser, во время его ученичества у Second Prophet. Внутри бурлит кипящая смесь заражённой крови, ожидающая освобождения из своей темницы.", "special_effect": "При попадании отнимает у противника небольшое количество крови."}, "moonseye-scalpel": {"description": "Поздравляем! Вы выиграли лотерею Rifle Spear."}, "moppet": {"description": "Как мы видим сходство в предметах, так и Vow часто усиливаются подражательным соответствием между изображением и его целью.", "special_effect": "При обычной атаке (M1) кукла принимает облик противника.\n\nОбычные атаки не наносят прямого урона: урон накапливается, пока вы не используете критический удар."}, "needles-eye": {"description": "Об этих рапирах известно немногое, кроме того, что это копии рапиры Duchess Thera Erisia, с которой она, как говорят, погибла в споре, будучи в огромном меньшинстве. Предание гласит, что на самом деле она пробилась сквозь натиск, но умерла от потери крови на руках своего благородного сына Nir, который вскоре принял её мантию."}, "night-axe": {"description": "Night Axe, оружие, мало известное в наши дни, выковали древние жители Minityrsa, и им владел Ekrim из Rouhlx Dyad, получивший прозвище Third's Eclipse. В паре со своим светящимся двойником Daybreak, Night Axe бросал длинные тени страха на древние поселения. Его история шепчется в сказаниях о неудержимой мощи и жуткой игре ночи и дня. Шаткие свидетельства говорят о том, что пара встретила мрачный конец от руки силы, которой они когда-то поклонялись, запечатав свою легенду в тени."}, "nocturne": {"description": "Эти парные клинки работы Celestial несут жуткое подобие сознания. По их длине тянутся светящиеся гобелены эфирного лунного света. Если прислушаться, можно почти различить шёпот или, возможно, плач. Известно, что клинки становятся тяжелее и неудобнее, если используются в несправедливых целях, словно судят поступки владельца. Поэтому считается, что раскрыть их истинный потенциал может лишь человек непоколебимой честности."}, "oath-blightsurger": {"description": "Древний браслет, дарованный ученикам Theros, чей носитель когда-то был почитаем в Legion."}, "officer-saber": {"description": "Характерная сабля офицера Authority. Обычно используется в рейдах Authority на спорные территории."}, "old-world-greatshield": {"description": "Искусно сделанный щит, скорее всего, до-Canticlysm эпохи. Тонкая работа указывает на прежнее использование в королевских кругах, хотя утверждать наверняка нельзя.", "special_effect": "Щит: при хвате одной рукой Стойка (Posture) персонажа увеличивается на бонус максимальной Стойки щита, но восстановление Стойки при парировании снижается на 40%."}, "palace-tachi": {"description": "Тёмная тати Threadcutter. Утяжелённая сплавами, она смещает центр масс дальше по клинку, давая медленную, но сокрушительную режущую силу.", "special_effect": "Это оружие получает бонус урона 5% от таланта Paired Soul и выигрывает от Poser's Ring."}, "pale-briar": {"description": "Посох Cardinal Церкви Starkindred, как говорят, покрытый ихором Celestial, чтобы наделить его силой Звёзд. Этот конкретный экземпляр попал в руки Maestro во время его обучения у Legion в вылазке против Церкви Starkindred."}, "pale-morning": {"description": "Молот исключительно тонкой работы, копия знаменитого молота, которым владел военачальник Canor в Первом веке Нового мира."}, "parrying-dagger": {"description": "Кинжал, который используют скорее как точку опоры для парирования, чем как самостоятельное оружие."}, "pars-glaive": {"description": "Ваше надёжное оружие."}, "petras-anchor": {"description": "Якорь судна «Petra's Dawn», прославленного плаванием между Luminant без помощи Дара Lightkeeper. Корабль, разумеется, не совершил обратного пути."}, "phantomcleave": {"description": "Простая катана из тонкого стекла, которую когда-то носил уважаемый мечник Vigil. По рассказам команды, после случайного захода в Voidsea и мечник, и клинок попали в странный вихрь. Правда ли это, неясно. Нашли лишь оружие, застрявшее в треснувшем корпусе, и горстку обезвоженных выживших, позже выброшенных на берег у ног Etris, без следов прежнего хозяина.", "special_effect": "Обычные атаки (M1) полностью игнорируют блок."}, "pleekstys-inferno": {"description": "На родине Tiran оружие часто делают из сколотого вулканического стекла вроде обсидиана. Хотя призматические лезвия по бокам хрупки, они острее любого металлического клинка. После восхождения Amorus Pleeksty и его первопроходческого Flamecharm многие Tiran вплетали цветочные узоры в свои макуауитли в знак почтения к Deepwoken. Из них этот экземпляр был подарком самому Pleeksty, пропитанным извергающимся и палящим жаром магмы, и пригоден лишь для тех, кто по-настоящему идёт по его стопам."}, "prototype-railblade": {"description": "Прототип оружия, созданный Ignition Union в надежде повысить свои шансы против обитателей Deep."}, "purple-cloud": {"description": "Завораживающий клинок из обсидиана и фиолетового цвета: кажется, что у меча есть собственная душа. Разумно обнажать его лишь ненадолго.", "special_effect": "Это оружие получает бонус урона 5% от таланта Paired Soul."}, "quartztone-pickaxe": {"description": "Кирка, сделанная из исключительно крупного кварцевого узла. Кристалл кропотливо настроен на частоту мантры и вызывает её эффекты при использовании."}, "quickfang": {"description": "Рапира, переданная вам предками."}, "railblade": {"description": "Ныне легендарный клинок, созданный Ignition Union, чтобы истреблять жутких врагов, таящихся глубже в Depths. Говорят, он постоянно излучает защитный жар, оберегающий владельца от коварного холода Eternal Gale.", "special_effect": "Критический удар поджигает врагов, которых он поразил."}, "rangescraper": {"description": "Переходя из рук в руки, призрак этого клинка, похоже, был пленён пустотой. Жуткий способ, которым он искажает пространство вокруг себя, несомненно, способствует его хрупкости, но сколько бы раз он ни разбивался, он всегда возвращается."}, "razor-cutlass": {"description": "Зазубренный кортик, сделанный по образцу печально известного жестокого укуса крылатки."}, "red-death": {"description": "Орудие Ministry Heartbleeder, тайной ячейки под началом 2nd Prophet, собирающей сведения безжалостными методами допроса. Наделённое гибридным размером двух разных стихов Song, оно использует Bloodrend, чтобы убрать все органические следы, и Shadowcast, чтобы убрать все следы эфира. Даже сам металл олеофобен и отталкивает органические масла и жидкости, поэтому копьё не оставляет ни отпечатков, ни следов."}, "repeater": {"description": "Недавнее изобретение оружейников Summer Company, огнестрельное оружие с высокой скорострельностью."}, "rifle-spear": {"description": "Доработка чертежей оружейника Rosen, выполненная оружейником Hierka, бывшим учеником Rosen. Говорят, Hierka скрывал, что был членом Bureau of Research при Authority, чтобы выкрасть секреты Summer Company.", "special_effect": "Активирует все таланты, эксклюзивные для Rifle и Spear."}, "rimebreakers": {"description": "Погружённые в бурю Ethiron и пропитанные морозом Kyrsan, эти обмотки из костей на кулаках — пронзительное отражение нынешнего состояния Kyrsgarde. Когда-то гордый и могучий народ, Kyrsan теперь оказались сбиты с ног и задыхаются под гнётом, почти без надежды на спасение. Возможно, схожая участь ждёт и ваших врагов, если они встретятся с этими орудиями боя."}, "rite-of-authority": {"description": "Невероятно искусно сделанная сабля, если её вообще можно так назвать. Она превосходно проводит thundercall: дуги перескакивают между заклёпками, покрывающими её по всей длине."}, "ritual-sacrifice": {"description": "Разве жертва не самый могущественный из всех ритуалов?"}, "ritual-spear": {"description": "Копьё, когда-то использовавшееся в ритуалах Gremor, посвящённых Navae, а теперь присвоенное по всему Eastern Luminant."}, "rockmaller": {"description": "Это всего лишь небольшой добытый кусок гораздо более мощного камня. Молчаливый, непримечательный, примерно такой же живой, как... ну, камень на палке. Но стоит взять его в руки, как чувствуешь необузданную силу, гудящую под шершавой поверхностью. Речь не об изящном оружии, а о грубом, жестоком разрушении, которое этот скромный осколок готов выпустить в ваших руках."}, "rosens-hellflame": {"description": "Источники вдохновения и озарения, которыми Rosen пользовался в странствиях, становятся яснее в некоторых его единичных работах. Способный по желанию извергать поток палящего пламени, Hellflame не исключение. Было время, когда Rosen не покидал мастерской, одержимый зловещим стремлением выплеснуть все накопленные знания целиком, как грешник на исповеди.", "special_effect": "Каждая вторая и четвёртая обычная атака (M1) накладывает горение или вызывает извержения при попадании."}, "rosens-peacemaker": {"description": "Шедевр, выкованный самим оружейником Rosen: революционное оружие, навсегда изменившее искусство боя. Они высоко ценятся на рынке как из-за исторической значимости этого огнестрельного оружия, так и из-за его эффективности."}, "rosens-roscoe": {"description": "Изящная ручная пушка, созданная тщательной кузнечной работой. Roscoe знаменует первое поколение настоящих револьверов с цилиндрическим стволом в Lumen. Хотя он медленнее скорострельных моделей Company, он выдаёт непревзойдённую мощь и точность, принеся ученику Rosen заслуженную плату за новшество."}, "sanguine-transfuser": {"description": "Вы наблюдаете, как некогда твёрдый осколок оживает в холодной кузне: расколотый клинок свободно впитывает свою нынешнюю биотическую форму. Проржавевший кинжал отваливается, оставляя осколок и кровь танцевать в спиральной форме. Когда они достигают уже слившегося Hemobloom, осколок расходится, отвергнутый кристаллизующейся кровью, теперь твёрдо отлитой в форму своего прародителя. Хотя реликвия была уничтожена, а ваш эксперимент провалился, то, что осталось, возможно, стоит потерянного."}, "scimitar": {"description": "Изогнутый клинок из саванн Markor. Хотя теперь они ассимилированы в Central Authority, народ Markor всё ещё хранит богатую культуру."}, "scoundrels-saber": {"description": "Прочная сабля Celtor с утяжелённым навершием, которой когда-то владел Traan Zakshun. Известный финтами и грязными приёмами, он бил врагов тяжёлым навершием так же часто, как и клинком.", "special_effect": "Критический удар наносит на 10% больше урона, если попадает в спину противника."}, "serpents-edge": {"description": "Вопреки общему мнению, Serpent's Edge на самом деле клинок работы Capra, а не Etrea. Режет он при этом не хуже любого etrean-клинка."}, "shadebolt": {"description": "Лук древнего Ganymede-кочевника, жившего в глубинах. Через запретные обряды Umbrite подчинили их воле и придали ему форму орудий, казавшихся почти живыми. Одни называли этого человека Shaman, другие так и не узнали имени."}, "shattered-katana": {"description": "Сделана по образцу легендарного клинка, которым, как говорят, владел King of Etrea, Splinterblade. Исключительно смертоносный клинок, быстро расправляющийся с тяжёлой бронёй.", "special_effect": "Это оружие получает бонус урона 5% от таланта Paired Soul и выигрывает от Poser's Ring."}, "shotel": {"description": "Клинок из Markor, ценимый воинами за способность без усилий проскальзывать мимо защиты врагов."}, "silass-cenotaph": {"description": "Само надгробие Silas Ardenstar, превращённое семьёй Spellhardt в корявый большой меч как жестокая шутка после его первой смерти. Его мумифицированная усохшая голова с окаменяющим взглядом теперь тоже в вашем распоряжении. Лик главы рода Ardenstar внушает страх многим даже после смерти."}, "silver-dagger": {"description": "Блестящий кинжал, покрытый серебряной пылью. Любим изгоями, мнящими себя модными."}, "silversix": {"description": "Пистолет, переданный вам предками."}, "skull-piercer": {"description": "Когда держишь клинок, кажется, что украшающие его черепа каким-то образом тёплые. Что это на самом деле?"}, "skyreap-blade": {"description": "Рёбра этого клинка, похоже, обладают неземной прочностью, неслыханной в этих землях. Ходят слухи, что это могут быть кости самих Edenkite."}, "smouldering-hallow": {"description": "Пропитанная извитыми корнями Ardfall, эта пушка не похожа ни на какую другую. Выкованная кузнецами Floating Keep, её праздничные тыквы выпускают разрушительное веселье. Невольно улыбаешься про себя, когда стреляешь из неё."}, "soulshot": {"description": "Сколько весит эта штука в заряженном виде?", "special_effect": "Урон сильно возрастает с каждым выстрелом по одному врагу."}, "soulthorn": {"description": "Говорят, ядро этого клинка, вихрящееся внутри, было высосано из Moonseye странником Celestial во время его путешествия по небесам. Его лезвие передаёт врагу режущую муку, оставляя духовные раны. Его прежний владелец, когда-то известный как Moonlight Prince, как говорят, был сведён с ума голосами, запертыми внутри. Держа его, вы слышите, как он шепчет прямо в ваш разум. Голоса внутри оплакивают свою искажённую судьбу: украденные из небесного свода, чтобы в итоге встретить ту же участь, что и Drowned.", "special_effect": "Каждая обычная атака (M1) накладывает на цель Soul Mark, до 3 зарядов."}, "soulwrought-axe": {"description": "Оружие, извлечённое из вашей души."}, "soulwrought-dagger": {"description": "Оружие, извлечённое из вашей души."}, "soulwrought-greatsword": {"description": "Оружие, извлечённое из вашей души."}, "soulwrought-gun": {"description": "Оружие, извлечённое из вашей души."}, "soulwrought-longsword": {"description": "Оружие, извлечённое из вашей души."}, "soulwrought-spear": {"description": "Оружие, извлечённое из вашей души."}, "sovereigns-punishment": {"description": "Церемониальный молот, символизирующий силу Закона Authority. Считался неудобным и негодным для боя. Пока вы не взяли его в руки."}, "spectral-grasp": {"special_effect": "Уникальный след взмаха и звуковые эффекты."}, "steel-maul": {"description": "Прочная кувалда, идеальная для сноса и стен, и людей."}, "steelscale-dusters": {"description": "Лёгкие кастеты, выкованные кузнецами Blade Temple. Те, кто заслужил место Jade Vigil, получают право носить их бусины и заковывать кулаки в сталь."}, "stiletto": {"description": "Удивительно тонкий клинок, который часто сравнивают с зубочисткой (и используют как неё)."}, "stoneheart": {"description": "Молот, собранный из останков одного из големов Duke Ishamon Erisia. Вызванные Резонансом герцога, они когда-то патрулировали его владения в Celtor до его падения. По донесениям шпионов, нанятых соперничающими дворянами города, он мог поддерживать лишь ограниченное число големов: приобретение Forge of Sin, похоже, расширило его возможности другими, более зловещими способами.", "special_effect": "Критический удар можно зарядить, удерживая клавишу. Анимацию заряда нельзя прервать. При заряде наносит больше урона и имеет больший радиус области."}, "stormseye": {"description": "Похитив его у вернувшейся экспедиции Union, Summer Company увидела огромную энергию, заключённую в медальонах Kyrsan, и создала этот уникально жестокий прототип. Rosen, по слухам, разразился громким хохотом, увидев чертёж, и сразу же одобрил его.", "special_effect": "При flourish выпускает ударную волну, оглушающую и отталкивающую противников. Перезарядка 10 с.\nПрименяет таланты Thundercall. Атаки в воздухе телепортируют вас к врагу."}, "summer-hullwrecker": {"description": "Антикварное творение Summer Company, созданное, чтобы вложить в ладони мощь огня линкора. Когда-то его называли шедевром, но вскоре его затмили более лёгкие винтовки. Однако в руках того, кто достаточно силён, чтобы им владеть, оно всё ещё способно обрушить разрушение, недоступное новым моделям."}, "summer-rifle": {"description": "Стандартное огнестрельное оружие производства Summer Company. Надёжное оружие, хотя и менее элегантное, чем их более дорогие модели."}, "sword-weapon": {"description": "Клинок тонкой работы, вероятно, фамильная ценность того, кто владел им, пока его не украли с останков."}, "tanto": {"description": "Кинжал, выкованный etrean-кузнецом. Говорят, танто обладает той же прочностью, что и катана, но в меньшем размере."}, "targe": {"description": "Круглый деревянный щит, который часто сочетают с копьём или коротким клинком.", "special_effect": "Щит: при хвате одной рукой Стойка (Posture) персонажа увеличивается на бонус максимальной Стойки щита, но восстановление Стойки при парировании снижается на 40%."}, "tenacity": {"description": "Вырезанный из чешуи самого Doom, этот щит был изготовлен по заказу Summer Company, а его чертежи разработал отважный Cpt. Greene. Использовав шкуру самого существа, предположили, что она может обладать некоторым сопротивлением его палящему дыханию. При проверке он справился блестяще, защитив нёсшего его Pathfinder от безжалостного натиска зверя. Увы, послушай они совет Greene и заплати вдвое больше, чтобы закрепить второй на спине владельца, тот мог бы защититься от обоих рядов зубов.", "special_effect": "Щит: при хвате одной рукой Стойка (Posture) персонажа увеличивается на бонус максимальной Стойки щита, но восстановление Стойки при парировании снижается на 40%."}, "the-barrel": {"description": "Эта громоздкая пушка когда-то стояла на королевском etrean-галеоне, но была поднята с обломков Summer Company и переделана в ручной вариант. По словам тех, кто пользовался ею до окончательного списания, она всё ещё неудобная."}, "the-death-knell": {"description": "Напоминание о том, что все песни должны закончиться.", "special_effect": "Критические удары расходуют здоровье, но лечат вас, если попадают."}, "the-endless-wave": {"description": "Самый большой набор одати, когда-либо изготовленный Etrea в годы расцвета: мало что в этом мире может сравниться с мастерством этой громадины."}, "the-flippers-of-fate": {"description": "Это не дым. Это пар."}, "the-golden-fool": {"description": "Отважные воины с золотыми ремнями, что сверкают, как солнце!"}, "the-long-tong-of-the-law": {"description": "Где крабовый СООООУС?", "special_effect": "Использует анимации Spear."}, "the-pastry-paster": {"description": "Готовить может любой, но великим стать способен лишь бесстрашный."}, "the-paths-defender": {"description": "Почитаемый щит, который надевают лишь те, кто прошёл собственный Path так, как считал нужным.", "special_effect": "Щит: при хвате одной рукой Стойка (Posture) персонажа увеличивается на бонус максимальной Стойки щита, но восстановление Стойки при парировании снижается на 40%."}, "the-rock": {"description": "Кому нужен меч?"}, "the-weaving-web": {"description": "Ой, посмотрите на этого малыша!..."}, "trident-spear": {"description": "Удивительно эффективное оружие, несмотря на то что раньше им пользовались рыбаки."}, "umbrite-witherblade": {"description": "Когда-то заброшенный каркас, ныне восстановленный вашими подношениями, пульсирует всё быстрее и быстрее... Его волокна скручиваются и трещат, тянутся поглотить кортик, а его форма искажается в грубую иллюзию оружия. Пропитанный минералами, которые знал раньше, он пропускает искажённый umbrite по своим скользким чернильным жилам. Каждый удар высасывает саму душу врагов, оставляя их иссохшими и сломленными.", "special_effect": "Обычные атаки (M1) накладывают 50% масштабированного урона как Wither."}, "unsung-scythern": {"description": "Выкованный в бурных огнях Canticlysm, Unsung Scythern стоит как свидетельство стойкости человечества перед лицом хаоса. Созданное древними руками, его лезвие несёт груз забытых историй и утраченных цивилизаций. Это оружие направляет эхо ушедшей эпохи, нашёптывая сказания о выживании. С каждым взмахом оно прорезает завесу времени."}, "untrained-fist": {"description": "Ваши голые кулаки. Стоит попробовать, правда?", "special_effect": "Атаки оружием наносят на 50% меньше урона."}, "vapormaw-carbine": {"description": "Экспериментальное паровое огнестрельное оружие: резервуар с паром под давлением даёт исключительную кинетическую силу, делая его способным на удивительно разрушительный результат."}, "vigil-longsword": {"description": "Несмотря на популярность катаны, Vigil Longsword отражает потребность Etrea в более экономичных процессах производства клинков. Тем не менее он считается не менее хорошим клинком."}, "vortex-echo": {"description": "Маленький пульсирующий вихрь ветра Ethiron бесконечно кружится внутри этих часов, задавая их резонирующим тикам вечный ритм. Его изящная рама цвета слоновой кости излучает неестественный холод, словно воздух вокруг скручивается под тяжестью какой-то потусторонней силы. Потянувшись, чтобы взяться за эфирную цепочку, вы чувствуете внезапный прилив, ощущение, не похожее ни на что другое: вас протаскивает сквозь саму ткань времени. В эти мимолётные мгновения вы чувствуете, что стали немного старше.", "special_effect": "Критический удар уменьшает все перезарядки на 30 секунд."}, "warden-ceremonial-sword": {"description": "Церемониальный клинок Authority Warden. Несмотря на положение на церемониях и торжественных мероприятиях, Warden из Authority — одни из самых свирепых воинов в арсенале Authority. Их присутствие на публичных событиях считается попыткой внушить страх врагам."}, "warmonger": {"description": "Warmonger ненавидит. Warmonger разрушает. Warmonger убивает."}, "weal-and-woe": {"description": "Парные копья, вытесанные из единого массивного осколка теневого обсидиана парой близнецов-Shadowcaster. Считается, что у близнецов уникальная совместимость с Vow: шёпоты их душ дополняют друг друга. Через одинаковые Vow, принятые близнецами, предметам можно придать форму сцепленности и парности. Владелец одного из таких предметов всегда чувствует местонахождение своего двойника. Эти копья не исключение: их сцепленность позволяет владельцу использовать приёмы обоих копий в гармонии."}, "whaling-knife": {"description": "Нож одного из печально известных Knives of Eylis, наёмников и убийц, которых боятся и презирают по всему миру. Имеет уникальный критический удар с повышенным шансом нанести критический урон, если вы владеете «Knife's Journey»."}, "winter-rifle": {"description": "Один из менее известных прототипов Rosen: эта винтовка использует вид мистицизма, не подобающий механическому гению."}, "withered-death-knell": {"description": "Напоминание о том, что все песни должны быть поглощены."}, "withered-gale-pale": {"description": "Наследие, запятнанное вашей рукой, но получившее зловещую силу в нечестивой кузне Leiuna. Известно, что ветер удерживает голоса в плену, и, держа его в руках, вы слышите искреннюю мольбу: Похороните кузню. Убейте её память. Жадность — их кинжал."}, "withered-phantomcleave": {"description": "Работа кузни выжигает воспоминание в сплавленном сосуде, истончая его форму до полупрозрачности. Силуэт мечника Vigil отражается из его глубин, угрюмый и лишённый всякой жизненной силы.", "special_effect": "Выигрывает от Poser's Ring."}, "wooden-staff": {"description": "Сбалансированный деревянный посох."}, "worldpainter-brush": {"description": "Могучая кисть, дарованная самым одарённым мастерам Lumen.", "special_effect": "При попадании накладывает эффект «ослепления»."}, "worldpiercer-gauntlets": {"description": "Жестокие перчатки тех, кто прорывает защиту безжалостной силой."}, "worshipper-longsword": {"description": "Клинок, выкованный известным Flamepriest и посвящённый кузне, в которой он был рождён."}, "worshippers-shield": {"description": "Щит с эмблемой Flamepriest. Поклонение Огню рассматривается как принятие дихотомии между Огнём и Морем и считает Deep главным врагом, а Огонь олицетворяет человечество.", "special_effect": "Щит: при хвате одной рукой Стойка (Posture) персонажа увеличивается на бонус максимальной Стойки щита, но восстановление Стойки при парировании снижается на 40%."}, "wraithclaw": {"description": "Связанный и сплетённый из волос и сухожилий, призрачный коготь формируется из обид тех, кого принесли в жертву для его создания. По всему Lumen многие верят, что голоса мёртвых несёт ветер. Так же многие верят, что ветры Lumen рождаются из кружащегося вихря Moonseye наверху. Возможно, эти голоса принадлежат Old World и оплакивают то, во что превратился Lumen."}, "wretched-mawblades": {"description": "Рождённые из извращённого эксперимента загадочных кузнецов Lightborn из Floating Keep, Mawblades — свидетельство несказанного предательства. Лишённые смертности и насильственно переделанные, замученные души внутри этих клинков терпят судьбу хуже смерти, их зубы вечно ноют, ведь они привязаны к ненасытному голоду разрушения."}, "wyrmtooth": {"description": "Исключительно длинный и неудобный клинок работы Etrea. Бесполезен в руках новичка, но смертелен в руках того, кто сумеет приспособиться к его неестественному центру тяжести."}, "ysleys-pyre-keeper": {"description": "Пара клинков, которыми когда-то пользовался High Curator of the Hive. Говорят, их создал 2nd Greatlord в дар 3rd, но из-за пацифизма они собирали пыль, пока их не приобрёл Ysley. Ярко горят Огнём Жизни. Атаки кинжалом во второй руке масштабируются от LHT."}, "zweihander": {"description": "Популяризированный Canor Borderwatcher, цвайхандер так же грозен, как и тяжёл."}};
